// Pure mapping for tests: mapAge(age, mode, cutoff, strength, horizon).
function mapAge(age,currentMode='equal',cutoff=12,strength=.5,horizon=88){
  const safeHorizon=Math.max(1,Number(horizon)||88),u=Math.max(0,Math.min(1,Number(age)/safeHorizon));
  if(currentMode==='recent') return safeHorizon*Math.pow(u,1.6);
  if(currentMode!=='childhood') return safeHorizon*u;
  const k=Math.max(.01,Math.min(safeHorizon-0.01,Number(cutoff)||12)),s=Math.max(0,Math.min(1,Number(strength)||0));
  // Integrate a smoothly increasing speed: childhood runs at w, then eases to 1.
  const w=1-.8*s;
  const F=a=>a<=k ? w*a+(1-w)*(a*a*a/(k*k)-.5*a*a*a*a/(k*k*k)) : a-.5*(1-w)*k;
  return Math.max(0,Math.min(safeHorizon,safeHorizon*F(Math.max(0,Math.min(safeHorizon,Number(age)||0)))/F(safeHorizon)));
}
